pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the sender and the timestamp to ensure wide coverage; value is fixed by the test via vm.deal
    function testFuzz_property(address sender, uint64 warpTime, uint64 warpBlock) public {
        // keep sender non-zero
        vm.assume(sender != address(0));

        // make times reasonable bounds (but wide)
        if (warpTime < 1) warpTime = 1;
        if (warpBlock < 1) warpBlock = 1;

        // Arrange: give sender enough ETH and set chain time/height
        uint256 pay = 10 ether;
        vm.deal(sender, pay);
        vm.warp(uint256(warpTime));
        vm.roll(uint256(warpBlock));

        // Act: call fallback with exactly 10 ether from fuzzed sender
        bool ok;
        vm.prank(sender);
        try c.f{value: pay}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: reference contract accepts exactly 10 ether payments to fallback (so call returns ok==true)
        // and updates pastBlockTime to a value strictly greater than zero; we observe acceptance via ok.
        // Mutant that requires 9 ether will cause this call with 10 ether to behave differently for some inputs
        assertTrue(ok);
    }
}

