pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the initial block timestamp and whether to advance time
    function testFuzz_property(address caller, uint256 warpDelta) public {
        // keep caller as a non-zero address
        vm.assume(caller != address(0));
        // bound warpDelta to a reasonably large range but allow zero
        warpDelta = bound(warpDelta, 0, 1 days);

        // fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // set an initial timestamp
        uint256 t0 = block.timestamp;
        // Optionally warp forward by warpDelta to create cases where timestamp increases
        if (warpDelta > 0) {
            vm.warp(t0 + warpDelta);
        } else {
            // ensure we can also test the case where timestamp does NOT increase (warpDelta == 0)
            vm.warp(t0);
        }

        // read previous pastBlockTime
        uint256 prev = c.pastBlockTime();

        // perform the payable call of exactly 10 ether from the caller
        vm.prank(caller);
        // call the fallback by sending to the contract address
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // we don't assert on ok here; either reference or mutant might transfer out funds on some blocks

        // After the call, the reference contract guarantees that pastBlockTime is only updated
        // when block.timestamp was strictly greater than the previous stored pastBlockTime.
        // In particular, when block.timestamp <= prev, the reference leaves pastBlockTime unchanged.
        // The mutant that removed the require(block.timestamp > pastBlockTime) can set pastBlockTime
        // to block.timestamp + 1 even when block.timestamp <= prev, breaking the monotonicity.

        // We assert a universal property the reference satisfies for all inputs: if current block.timestamp
        // is <= prev, then pastBlockTime remains equal to prev after calling fallback.
        uint256 after = c.pastBlockTime();
        if (block.timestamp <= prev) {
            assertTrue(after == prev);
        } else {
            // when block.timestamp > prev the reference may update pastBlockTime to block.timestamp + 1
            // so for generality we assert that after is at least prev (monotonic non-decreasing)
            assertTrue(after >= prev);
        }
    }
}

