pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 sendAmount, uint256 ts, uint256 startPast) public {
        // keep domain reasonable: sendAmount should be 10 ether to trigger fallback's require
        vm.assume(sendAmount == 10 ether);
        // ensure timestamps fit in uint256 -> uint64 but keep wide
        vm.assume(ts <= type(uint64).max);
        // set an initial pastBlockTime by directly warping and invoking fallback once via a helper actor
        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);

        // Set the chain timestamp to a chosen value and set c.pastBlockTime to startPast by using an initial call
        // We warp to ts and then set the contract's pastBlockTime via a fallback call that would set it to block.timestamp+1
        // but to allow startPast to be arbitrary we will simulate starting pastBlockTime by first warping and calling when desired
        // Set up initial state: warp to startPast - 1 so that a call sets pastBlockTime = (startPast - 1)+1 = startPast
        uint256 beforeWarp;
        if (startPast == 0) {
            beforeWarp = 0; // warp to 0 is fine
        } else {
            beforeWarp = startPast - 1;
        }

        vm.warp(beforeWarp);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Record the stored pastBlockTime after this initial setup
        uint256 recorded = c.pastBlockTime();

        // Now perform the decisive call: warp to ts and call fallback again from some caller; the behaviour differs if ts <= recorded-1
        vm.warp(ts);
        address caller = address(0xBEEF);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // single assertion: in the correct contract, after the second call, pastBlockTime must be >= recorded
        // More specifically: reference requires block.timestamp > previous pastBlockTime to update, otherwise it remains unchanged.
        // Since we cannot know whether block.timestamp > recorded at test-time for a given fuzz input, we assert the general monotonicity:
        // after the second call, c.pastBlockTime() >= recorded
        // The mutant (which always writes pastBlockTime = block.timestamp+1) can make this fail for some inputs (e.g., ts very small), so fuzz will find them.
        assertTrue(c.pastBlockTime() >= recorded);
    }
}

