contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a timestamp delta (0 or positive) to control block time progression
    function testFuzz_property(address caller, uint256 warpDelta) public {
        // Keep caller as a non-zero address
        vm.assume(caller != address(0));

        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // ensure initial pastBlockTime is 0 (constructor leaves it 0)
        uint256 before = c.pastBlockTime();

        // First call: send exactly 10 ether from caller at current timestamp
        vm.prank(caller);
        c.f{value: 10 ether}();

        uint256 afterFirst = c.pastBlockTime();

        // Now control timestamp progression: warpDelta == 0 keeps same timestamp; >0 advances
        // bound warpDelta to a reasonable range so vm.warp doesn't overflow
