        if (d > 0) {
            vm.warp(block.timestamp + d);
        }

        // Record before second call
        uint256 beforeSecond = c.pastBlockTime();

        // Second call: same caller sends 10 ether again
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        c.f{value: 10 ether}();

        uint256 afterSecond = c.pastBlockTime();

        // General rule (single assertion): If the block timestamp did NOT advance between the two calls (d==0),
