        // The mutant (which removed the require) can change pastBlockTime even when timestamp did not advance,
        // so this property will fail for some inputs (e.g., when d==0).

        bool ok;
        if (d == 0) {
            ok = (afterSecond == beforeSecond);
        } else {
            // when time advanced, reference may update pastBlockTime; accept either
            ok = true;
        }

        assertTrue(ok);
    }
}

