        vm.warp(block.timestamp + 1);
        vm.prank(caller);
        c.f{value: 10 ether}();

        uint before = c.pastBlockTime();

        // Now prepare the next call. We want to test both cases: same timestamp (no advance) and advanced timestamp.
        if (advanceTimestamp) {
            // advance timestamp strictly so reference contract's require(block.timestamp > pastBlockTime) can succeed
            // set timestamp to a large value to ensure strict increase over stored pastBlockTime
            vm.warp(block.timestamp + 1000);
        } else {
            // keep timestamp equal (no advance)
            vm.warp(block.timestamp);
        }

        // make the second call which sends exactly 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        uint after = c.pastBlockTime();

        // General property: the reference contract requires block.timestamp > previous pastBlockTime to update pastBlockTime.
        // Therefore, when we did NOT advance the timestamp (advanceTimestamp == false), the reference must NOT have increased pastBlockTime.
        // This single assertTrue reads c's public getter and will hold for the reference contract for all inputs,
        // while the mutant (which removed the timestamp check) can violate it when advanceTimestamp == false.
        assertTrue(advanceTimestamp ? after >= before : after == before);
    }
