contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz blockNumberModulo15 to let fuzzer pick a block.number such that block.number % 15 == k
    // and fuzz timestampOffset to ensure block.timestamp > pastBlockTime
    function testFuzz_property(uint256 blockNumberModulo15, uint256 timestampOffset, address sender) public {
        // keep modulo in 0..14
        uint256 k = blockNumberModulo15 % 15;
        // ensure sender is non-zero
        vm.assume(sender != address(0));

        // Set up chain state: choose a block number whose %15 == k
        // vm.roll takes absolute block number; pick a base large block to avoid low-number cornercases
        uint256 targetBlock = 1000 + k;
        vm.roll(targetBlock);

        // Ensure timestamp is strictly greater than pastBlockTime (initially 0) by setting a positive timestamp
        uint256 baseTime = block.timestamp;
        uint256 ts = baseTime + 1 + (timestampOffset % 1000);
        vm.warp(ts);

        // Fund the sender so they can send 10 ether
        vm.deal(sender, 20 ether);

        // Make the call: exactly 10 ether required by contract
        vm.prank(sender);
        c.f{value: 10 ether}();

        // After call: reference contract empties its balance iff block.number % 15 == 0
        // So we assert that (address(c).balance == 0) == (block.number % 15 == 0)
        bool balZero = address(c).balance == 0;
        bool cond = (block.number % 15 == 0);
        assertTrue(balZero == cond);
    }
